package com.hbm.machine.generator.stirling;
import com.hbm.hazard.HbmHazards;import com.hbm.multiblock.DummyableBlock;import com.hbm.machine.generator.steamengine.*;import com.hbm.registry.HbmSounds;import com.mojang.serialization.MapCodec;import java.util.List;import net.minecraft.core.*;import net.minecraft.sounds.SoundSource;import net.minecraft.world.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.level.storage.loot.LootParams;import net.minecraft.world.level.storage.loot.parameters.LootContextParams;import net.minecraft.world.phys.BlockHitResult;
/** Source true3x2x3 offset1 body,4 independent power outlets, exact gear repair and missing-cog drop state. */
public final class StirlingBlock extends DummyableBlock {
 public final StirlingKind kind;public StirlingBlock(StirlingKind kind){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());this.kind=kind;}
 @Override protected MapCodec<? extends DummyableBlock> codec(){return simpleCodec(p->new StirlingBlock(kind));}@Override public int[] dimensions(){return new int[]{1,0,1,1,1,1};}@Override public int offset(){return 1;}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new StirlingBlockEntity(pos,state):isPort(state)?new StirlingProxy(pos,state):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,StirlingContent.ENTITY.get(),StirlingBlockEntity::tick):null;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);if(level.isClientSide)return;var core=pos.relative(placementFacing(state),-offset());for(var side:List.of(Direction.WEST,Direction.EAST,Direction.NORTH,Direction.SOUTH))setPort(level,core.relative(side),true);if(level.getBlockEntity(core) instanceof StirlingBlockEntity machine&&StirlingItem.broken(stack)){machine.hasCog=false;machine.setChanged();}}
 private StirlingBlockEntity core(BlockGetter level,BlockPos pos){var found=findCore(level,pos);return found!=null&&level.getBlockEntity(found) instanceof StirlingBlockEntity machine?machine:null;}
 private InteractionResult insertGear(Level level,BlockPos pos,Player player,ItemStack held){if(level.isClientSide)return InteractionResult.SUCCESS;if(player.isShiftKeyDown())return InteractionResult.PASS;var machine=core(level,pos);if(machine==null||machine.hasCog||!held.is(SteamEngineContent.GEAR.get())||LargeGearItem.metadata(held)!=kind.gear)return InteractionResult.PASS;held.shrink(1);machine.hasCog=true;machine.setChanged();level.playSound(null,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,HbmSounds.get("item.upgradePlug"),SoundSource.BLOCKS,1.5F,.75F);return InteractionResult.SUCCESS;}
 @Override protected ItemInteractionResult useItemOn(ItemStack held,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){var tool=super.useItemOn(held,state,level,pos,player,hand,hit);if(tool!=ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION)return tool;return insertGear(level,pos,player,held)==InteractionResult.PASS?ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION:ItemInteractionResult.sidedSuccess(level.isClientSide);}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){return level.isClientSide?InteractionResult.SUCCESS:InteractionResult.PASS;}
 @Override public boolean onDestroyedByPlayer(BlockState state,Level level,BlockPos pos,Player player,boolean harvest,net.minecraft.world.level.material.FluidState fluid){if(!level.isClientSide&&harvest&&core(level,pos)!=null)return true;return super.onDestroyedByPlayer(state,level,pos,player,harvest,fluid);}
 @Override public void playerDestroy(Level level,Player player,BlockPos pos,BlockState state,BlockEntity original,ItemStack tool){var machine=core(level,pos);try{super.playerDestroy(level,player,pos,state,machine==null?original:machine,tool);}finally{if(machine!=null&&core(level,pos)==machine)level.removeBlock(pos,false);}}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder params){var machine=params.getOptionalParameter(LootContextParams.BLOCK_ENTITY) instanceof StirlingBlockEntity found?found:null;if(machine==null){var origin=params.getOptionalParameter(LootContextParams.ORIGIN);if(origin!=null)machine=core(params.getLevel(),BlockPos.containing(origin));}var result=new ItemStack(this);if(machine!=null&&!machine.hasCog)result.set(HbmHazards.LEGACY_METADATA.get(),1);return List.of(result);}
}
